import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from 'react-router-dom'; 
import "./RiverDashboard.css";

const DEBUG_API = "http://127.0.0.1:8000/api/weather/debug-read-s3";

const RiverDashboard = () => {
  const navigate = useNavigate();
  
  // --- STATE ---
  const [forecastData, setForecastData] = useState([]);
  const [limeData, setLimeData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [lastUpdated, setLastUpdated] = useState("");
  const [currentTime, setCurrentTime] = useState(new Date());

  // --- HELPERS ---
  const getStatus = (level) => {
    const val = parseFloat(level);
    if (val < 5.5) return { label: "Normal", class: "status-normal", color: "#10b981", bg: "#d1fae5" }; 
    if (val < 6.0) return { label: "Caution", class: "status-caution", color: "#f59e0b", bg: "#fef3c7" }; 
    return { label: "Warning", class: "status-critical", color: "#ef4444", bg: "#fee2e2" }; 
  };

  // --- EFFECTS ---
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const fetchForecast = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "forecast_output.csv" } });
        if (response.data.status === "success") {
          const rawLines = response.data.preview;
          const parsedData = rawLines.slice(1).map((line) => {
              const cols = line.split(",");
              const level = cols[cols.length - 1]?.trim();
              return { level: parseFloat(level).toFixed(2), status: getStatus(level) };
            }).filter((item) => !isNaN(item.level));
          setForecastData(parsedData);
          setLastUpdated(new Date().toLocaleTimeString("en-US", {hour: '2-digit', minute:'2-digit'}));
        }
      } catch (err) {
        console.error("Forecast API error:", err);
        setError("Failed to fetch forecast data");
      }
    };

    const fetchLimeInsights = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "lime_short_sentences_and_labels.txt" } });
        if (response.data.status === "success") {
          setLimeData(response.data.preview);
        }
      } catch (err) {
        console.error("LIME API error:", err);
      }
    };

    const loadAllData = async () => {
      setLoading(true);
      await Promise.all([fetchForecast(), fetchLimeInsights()]);
      setLoading(false);
    };

    loadAllData();
  }, []);

  // --- RENDER HELPERS ---
  const nextHour = forecastData[0] || { level: "--", status: getStatus(0) };
  const currentLevel = (parseFloat(nextHour.level) - 0.17).toFixed(2);
  const currentStatus = getStatus(currentLevel);

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Initializing AI Models...</p></div>;
  if (error && forecastData.length === 0) return <div className="rd-error"><h3>System Offline</h3><p>{error}</p></div>;

  return (
    <div className="rd-container">
      
      {/* --- HEADER --- */}
      <header className="rd-header">
        <div className="rd-header-top">
          <div className="rd-wrapper rd-flex-between">
            <div className="rd-gov-text">
              <span className="rd-pill">Govt. of India</span>
              <span className="rd-sep">•</span>
              Ministry of Electronics & IT (MeitY) Project
            </div>
            <div className="rd-time-display">
              <i className="fas fa-clock"></i>
              {currentTime.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' })}
            </div>
          </div>
        </div>
        <div className="rd-nav-bar">
          <div className="rd-wrapper rd-flex-between">
            <div className="rd-brand">
              <div className="rd-logo-box"><i className="fas fa-water"></i></div>
              <div>
                <h2>Periyar Monitor</h2>
                <small>AI-Integrated Flood Warning System</small>
              </div>
            </div>
            <nav className="rd-nav-links">
              <button onClick={() => navigate('/')}>Home</button>
              <button className="active">River Dashboard</button>
              <button onClick={() => navigate('/weather-map')}>Weather Map</button>
            </nav>
          </div>
        </div>
      </header>

      {/* --- MAIN DASHBOARD GRID --- */}
      <main className="rd-main-grid rd-wrapper">
        
        {/* --- LEFT COLUMN: LIVE STATUS (Sticky) --- */}
        <aside className="rd-col-left">
          
          {/* Status Card */}
          <div className={`rd-status-card ${nextHour.status.class}`}>
            <div className="rd-status-icon">
               {nextHour.status.label === "Normal" ? <i className="fas fa-check-circle"></i> : <i className="fas fa-exclamation-triangle"></i>}
            </div>
            <div className="rd-status-content">
              <span className="label">Current Condition</span>
              <h3>{nextHour.status.label.toUpperCase()}</h3>
              <p>Safe levels observed at Kalady station.</p>
            </div>
          </div>

          {/* Live Metrics Block */}
          <div className="rd-panel">
            <div className="rd-panel-header">
              <h4>Real-Time Sensors</h4>
              <span className="live-dot"></span>
            </div>
            
            <div className="rd-metric-large">
              <div className="value">{currentLevel} <small>m</small></div>
              <div className="sub">Current Water Level</div>
            </div>

            <div className="rd-divider-line"></div>

            <div className="rd-metric-row">
              <div className="metric">
                <span className="val">{nextHour.level}m</span>
                <span className="lbl">1-Hr Forecast</span>
              </div>
              <div className="metric">
                <span className="val">98.5%</span>
                <span className="lbl">Model Confidence</span>
              </div>
            </div>
            
            <div className="rd-update-info">
              Last Sensor Update: {lastUpdated}
            </div>
          </div>
        </aside>

        {/* --- RIGHT COLUMN: PREDICTION & ANALYSIS --- */}
        <section className="rd-col-right">
          
          {/* 6-Hour Timeline */}
          <div className="rd-panel">
            <div className="rd-panel-header">
              <h4><i className="fas fa-chart-line"></i> 6-Hour Predictive Model</h4>
            </div>
            <div className="rd-timeline-scroll">
              {forecastData.slice(0, 6).map((data, index) => (
                <div key={index} className="rd-timeline-node">
                  <div className="t-time">H+{index + 1}</div>
                  <div className="t-card" style={{borderBottom: `4px solid ${data.status.color}`}}>
                    <div className="t-val">{data.level}m</div>
                    <div className="t-status" style={{color: data.status.color}}>{data.status.label}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* AI Insights Feed */}
          <div className="rd-panel">
            <div className="rd-panel-header">
              <h4><i className="fas fa-brain"></i> Explainable AI Insights (LIME)</h4>
              <span className="rd-tag">Generated by XAI Engine</span>
            </div>
            
            <div className="rd-feed-container">
              {limeData.length > 0 ? (
                limeData.slice(0, 6).map((line, index) => {
                  const statusColor = forecastData[index]?.status?.color || "#ccc";
                  return (
                    <div key={index} className="rd-feed-item">
                      <div className="rd-feed-line" style={{backgroundColor: statusColor}}></div>
                      <div className="rd-feed-content">
                        <div className="rd-feed-meta">
                          <span className="rd-time-badge">H+{index + 1}</span>
                        </div>
                        <p className="rd-feed-text">{line}</p>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="rd-empty">Analyzing data patterns...</div>
              )}
            </div>
          </div>

        </section>
      </main>
    </div>
  );
};

export default RiverDashboard;
